    return redirect("/", code=302)

if __name__ == '__main__':
    # تشغيل الخادم على جميع الواجهات (0.0.0.0) وعلى المنفذ 5000.
    # يمكنك تغيير المنفذ حسب حاجتك، لكن 5000 جيد للاختبار.
    # debug=False للحفاظ على سرية العمليات.
    app.run(host='0.0.0.0', port=5000, debug=False)
